import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"【Глава 3】 Удалённое подключение","description":"","frontmatter":{},"headers":[],"relativePath":"ru/document/level-0/ch03-ssh.md","filePath":"ru/document/level-0/ch03-ssh.md","lastUpdated":1751833085000}`),a={name:`ru/document/level-0/ch03-ssh.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="【глава-3】-удаленное-подключение" tabindex="-1">【Глава 3】 Удалённое подключение <a class="header-anchor" href="#【глава-3】-удаленное-подключение" aria-label="Permalink to “【Глава 3】 Удалённое подключение”">​</a></h1><h2 id="_3-1-удаленное-подключение-к-vps-putty" tabindex="-1">3.1 Удалённое подключение к VPS (PuTTY) <a class="header-anchor" href="#_3-1-удаленное-подключение-к-vps-putty" aria-label="Permalink to “3.1 Удалённое подключение к VPS (PuTTY)”">​</a></h2><p>Во-первых, поскольку Windows является самой распространённой операционной системой среди новичков, в этой статье мы будем использовать её в качестве примера.</p><p>Во-вторых, хотя PowerShell и WSL в Windows 10 и выше также предоставляют удобные инструменты для работы по SSH, не все версии Windows имеют эти компоненты. Поэтому в этой статье мы рассмотрим подключение по SSH с помощью старого доброго PuTTY. (После подключения по SSH действия во всех программах будут одинаковыми.)</p><p>Итак, давайте начнём.</p><ol><li><p>Перейдите на <a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html" target="_blank" rel="noreferrer">официальный сайт</a> PuTTY и скачайте версию, подходящую для вашей операционной системы (в этой статье мы будем использовать 64-битную версию).</p><p><img src="/assets/ch03-img01-putty-download.Bz5MUwAJ.png" alt="Скачать PuTTY" width="1197" height="787"></p></li><li><p>Запустите PuTTY. Откроется главное окно программы. Теперь возьмите <a href="./ch02-preparation.html#_21-получение-vps">блокнот</a>, в который вы записывали информацию в предыдущей главе, и введите <strong>IP-адрес</strong> и <strong>порт</strong> вашего VPS в соответствующие поля (на скриншоте ниже). Чтобы не вводить эти данные каждый раз, можно сохранить сеанс (Saved Sessions). В дальнейшем вы сможете загрузить сохранённые настройки одним кликом.</p><p><img src="/assets/ch03-img02-putty-settings.DjkSkJO_.png" alt="Настройка PuTTY" width="466" height="448"></p></li><li><p>Рекомендуем установить значение <code>keepalive</code> в разделе <code>Connection</code> равным <code>60</code> секундам, чтобы предотвратить разрыв SSH-соединения, если вы долгое время не будете выполнять никаких действий. Не забудьте снова сохранить настройки.</p><p><img src="/assets/ch03-img03-putty-keepalive.BlaoAerP.png" alt="Предотвращение разрывов соединения" width="466" height="448"></p></li></ol><div class="warning custom-block"><p class="custom-block-title">Внимание</p><p>После любых изменений настроек PuTTY необходимо сохранить сеанс, иначе они будут потеряны при закрытии программы.</p></div><ol start="4"><li><p>Нажмите кнопку &quot;Open&quot;, чтобы открыть окно SSH-подключения. Введите имя пользователя и пароль для подключения к вашему VPS (в этой статье предполагается, что имя пользователя по умолчанию — <code>root</code>. Обратите внимание, что при вводе пароля в Linux не отображаются символы <code>******</code>. Это сделано для того, чтобы скрыть длину пароля. Не пугайтесь, ваша клавиатура в порядке!).</p><p><img src="/assets/ch03-img04-ssh-login.CzV3PNlG.png" alt="Подключение по SSH" width="835" height="640"></p></li></ol><h2 id="_3-2-успешное-подключение-по-ssh-знакомство-с-команднои-строкои" tabindex="-1">3.2 Успешное подключение по SSH! Знакомство с командной строкой! <a class="header-anchor" href="#_3-2-успешное-подключение-по-ssh-знакомство-с-команднои-строкои" aria-label="Permalink to “3.2 Успешное подключение по SSH! Знакомство с командной строкой!”">​</a></h2><ol><li><p>Если вы всё сделали правильно, вы увидите примерно такой экран, как на рисунке ниже. Это означает, что вы успешно подключились к серверу:</p><p><img src="/assets/ch03-img05-ssh-login-success.l_VdE5HU.png" alt="Первое подключение к VPS" width="835" height="640"></p><p>Этот экран — аналог «рабочего стола» на удалённом сервере, но здесь нет привычных значков, курсора мыши и ярких цветов. Только текст. Это и есть <strong>командная строка</strong> — <em>Command Line Interface</em> или сокращённо <em>CLI</em>.</p><p>Все дальнейшие действия вам придётся выполнять в командной строке, как хакер в кино. Возможно, поначалу это покажется вам непривычным, но поверьте, в использовании командной строки нет ничего страшного или сложного. По сути, это всего лишь способ взаимодействия с компьютером с помощью текстовых команд вместо графического интерфейса. <strong>Вы пишете команду, а компьютер её выполняет.</strong></p></li><li><p>Теперь можете немного осмотреться и познакомиться с командной строкой. На этом экране уже есть полезная информация, например, версия ядра системы (в данном случае <code>4.19.37-5</code>), время последнего входа в систему, IP-адрес и т.д. Конечно, в зависимости от VPS, ваш экран может выглядеть немного иначе.</p></li><li><p>Обратите внимание на последнюю строку командной строки. Слева от мигающего курсора находится набор символов. В данном случае это <code>root@vps-server:~#</code>. Что это значит? Всё просто:</p><ul><li>Текущий пользователь: <code>root</code>.</li><li>Имя сервера, на котором работает пользователь <code>root</code>: <code>vps-server</code>.</li><li>Текущий каталог, в котором находится пользователь <code>root</code>: <code>~</code>.</li><li>Символ <code>#</code> указывает на то, что после него можно вводить команды.</li></ul><p>Первые два пункта интуитивно понятны и не требуют пояснений. Третий пункт относится к файловой системе Linux. Сейчас вам не нужно вдаваться в подробности, достаточно знать, что <code>~</code> — это «домашний каталог» текущего пользователя. Четвёртый пункт, символ <code>#</code>, также не требует особого внимания. Просто знайте, что в дальнейшем все команды, которые вам нужно будет вводить, будут начинаться с <code>#</code> или <code>$</code>. Это будет означать, что <strong>после</strong> этого символа нужно ввести команду (поэтому при копировании команд <strong>копируйте только текст после</strong>, без символа <code>#</code> или <code>$</code>).</p></li></ol><h2 id="_3-3-первое-обновление-программного-обеспечения-linux" tabindex="-1">3.3 Первое обновление программного обеспечения Linux! <a class="header-anchor" href="#_3-3-первое-обновление-программного-обеспечения-linux" aria-label="Permalink to “3.3 Первое обновление программного обеспечения Linux!”">​</a></h2><ol><li><p>Так же, как и ваш телефон, будь то Android или iPhone, Linux нуждается в регулярном обновлении программного обеспечения для получения исправлений безопасности и новых функций. В Linux каждое приложение называется «пакетом» (package). А программа, которая управляет пакетами, называется «менеджером пакетов» (Package Manager). С помощью менеджера пакетов можно устанавливать, обновлять и удалять программы, а также обновлять саму систему Linux. Менеджеры пакетов Linux очень мощные, но сейчас вам достаточно знать, что в Debian используется менеджер пакетов <code>apt</code>. Давайте обновим систему с помощью <code>apt</code>, чтобы вы познакомились с его основными функциями.</p></li><li><p>Базовые команды Linux:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Номер</th><th style="text-align:center;">Команда</th><th style="text-align:left;">Описание</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-01</code></td><td style="text-align:center;"><code>apt update</code></td><td style="text-align:left;">Проверить обновления</td></tr><tr><td style="text-align:center;"><code>cmd-02</code></td><td style="text-align:center;"><code>apt upgrade</code></td><td style="text-align:left;">Установить обновления</td></tr></tbody></table></li><li><p>Введите первую команду, чтобы получить информацию об обновлениях:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Затем введите вторую команду. При появлении запроса на подтверждение установки <code>(Y/n)</code> введите <code>y</code> и нажмите Enter, чтобы начать установку.</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> upgrade</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Весь процесс показан на гифке ниже:</p><p><img src="/assets/ch03-img06-apt-upgrade-full.-w3BBGrx.gif" alt="Демонстрация процесса обновления" width="839" height="644"></p></li></ol><h2 id="_3-4-ваш-прогресс" tabindex="-1">3.4 Ваш прогресс <a class="header-anchor" href="#_3-4-ваш-прогресс" aria-label="Permalink to “3.4 Ваш прогресс”">​</a></h2><p><strong>Поздравляем, вы сделали ещё один важный шаг!</strong> Теперь вы умеете подключаться к своему серверу по SSH! Но что делать после подключения, кроме обновления системы? Узнаем в следующей главе!</p><blockquote><p>⬛⬛⬛⬜⬜⬜⬜⬜ 37.5%</p></blockquote>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};